examples.code:
X = rand(200, 2);
Y = categorical(X(:, 1) > 0.6 & X(:, 2) > 0.3, [false true], {'out', 'in'});
t = fitctree(X, Y, 'MaxNumSplits', 3);
view(t)
predict(t, [0.8 0.5; 0.2 0.9])
resubLoss(t)

x = linspace(0, 2*pi, 200)';
y = sin(x) + 0.1*randn(200, 1);
r = fitrtree(x, y, 'MinLeafSize', 15);
plot(x, y, '.', x, predict(r, x), 'LineWidth', 1.5)
round(resubLoss(r), 4)

X = [randn(50, 2); randn(50, 2) + 2.5];
Y = [ones(50, 1); 2*ones(50, 1)];
m = fitcknn(X, Y, 'NumNeighbors', 5);
[label, score] = predict(m, [0 0; 1.25 1.25; 3 3])

X = [mvnrnd([0 0], [1 0; 0 1], 100); mvnrnd([2 2], [3 1; 1 0.5], 100)];
Y = [ones(100, 1); 2*ones(100, 1)];
lin = fitcdiscr(X, Y);
quad = fitcdiscr(X, Y, 'DiscrimType', 'quadratic');
nb = fitcnb(X, Y);
round([resubLoss(lin), resubLoss(quad), resubLoss(nb)], 3)
round(lin.Mu, 2)
[x1, x2] = meshgrid(linspace(-3, 7, 150), linspace(-3, 5, 120));
g = predict(quad, [x1(:) x2(:)]);
contour(x1, x2, reshape(g, size(x1)), [1.5 1.5], 'k'), hold on, gscatter(X(:, 1), X(:, 2), Y), hold off

t = 2*pi*rand(150, 1);
X = [0.5*randn(150, 2); [2.5*cos(t), 2.5*sin(t)] + 0.3*randn(150, 2)];
Y = [-ones(150, 1); ones(150, 1)];
m = fitcsvm(X, Y, 'KernelFunction', 'gaussian', 'KernelScale', 'auto', 'Standardize', true);
resubLoss(m)
predict(m, [0 0; 2.5 0])
[x1, x2] = meshgrid(linspace(-4, 4, 100));
[~, s] = predict(m, [x1(:) x2(:)]);
contour(x1, x2, reshape(s(:, 2), size(x1)), [0 0], 'k', 'LineWidth', 1.5), hold on, gscatter(X(:, 1), X(:, 2), Y), hold off

x = (1:50)';
y = 2*x + 5 + 3*randn(50, 1);
r = fitrsvm(x, y, 'KernelFunction', 'linear');
round(predict(r, [10; 40])')

c = [0 0; 3 0; 0 3; 3 3];
X = [randn(40, 2) + c(1, :); randn(40, 2) + c(2, :); randn(40, 2) + c(3, :); randn(40, 2) + c(4, :)];
Y = repelem((1:4)', 40);
m1 = fitcecoc(X, Y);
m2 = fitcecoc(X, Y, 'Learners', templateTree('MaxNumSplits', 4), 'Coding', 'onevsall');
size(m1.CodingMatrix), size(m2.CodingMatrix)
predict(m1, c)'
round([resubLoss(m1), resubLoss(m2)], 3)

X = rand(300, 4);
Y = categorical(X(:, 1) + X(:, 2).^2 + 0.2*randn(300, 1) > 0.9);
bag = fitcensemble(X, Y, 'Method', 'Bag', 'NumLearningCycles', 60);
round(oobLoss(bag), 3)
boost = fitcensemble(X, Y, 'Method', 'AdaBoostM1', 'NumLearningCycles', 60);
round(resubLoss(boost), 3)
r = fitrensemble(X, X(:, 1).^2 + X(:, 3), 'Method', 'LSBoost', 'NumLearningCycles', 80);
round(resubLoss(r), 4)

X = randn(500, 20);
Y = X(:, 3) - 2*X(:, 7) + 0.3*randn(500, 1) > 0;
m = fitclinear(X, Y, 'Learner', 'logistic', 'Regularization', 'lasso', 'Lambda', 0.01);
nnz(m.Beta)
round(m.Beta([3 7])', 1)
round(resubLoss(m), 3)
k = fitckernel(X(:, 1:2), sum(X(:, 1:2).^2, 2) > 1.5);
round(resubLoss(k), 3)

t = linspace(0, 3*pi, 150)';
X = [t.*cos(t), t.*sin(t); -t.*cos(t), -t.*sin(t)]/5 + 0.05*randn(300, 2);
Y = [ones(150, 1); 2*ones(150, 1)];
net = fitcnet(X, Y, 'LayerSizes', [20 20]);
round(resubLoss(net), 3)
x = linspace(-3, 3, 100)';
r = fitrnet(x, sin(2*x) + 0.05*randn(100, 1), 'LayerSizes', 20, 'Activations', 'tanh');
plot(x, sin(2*x), x, predict(r, x), '--'), legend('true', 'network')

x = [0 1 2 3.5 4 5.5 6]';
y = sin(x);
gp = fitrgp(x, y, 'KernelFunction', 'squaredexponential');
xn = linspace(0, 7, 200)';
[m, s, int] = predict(gp, xn);
plot(xn, m, x, y, 'o', xn, int, 'k:'), legend('mean', 'data', '95% interval')
round(predict(gp, [1; 4.75])', 2)

X = randn(400, 2);
Y = double(X(:, 1).*X(:, 2) + 0.5*randn(400, 1) > 0);
tr = 1:200; te = 201:400;
deep = fitctree(X(tr, :), Y(tr));
shallow = fitctree(X(tr, :), Y(tr), 'MaxNumSplits', 4);
round([resubLoss(deep), loss(deep, X(te, :), Y(te)); resubLoss(shallow), loss(shallow, X(te, :), Y(te))], 3)
[lab, sc] = resubPredict(shallow);
size(sc)

X = randn(300, 2);
Y = double(X(:, 1).*X(:, 2) + 0.5*randn(300, 1) > 0);
splits = [1 4 16 64];
cvl = zeros(size(splits));
for k = 1:4
    cvl(k) = kfoldLoss(crossval(fitctree(X, Y, 'MaxNumSplits', splits(k)), 'KFold', 5));
end
round(cvl, 3)

x = linspace(0, 1, 60)';
y = 3*x + 0.2*randn(60, 1);
predfun = @(xtr, ytr, xte) [ones(size(xte)) xte]*([ones(size(xtr)) xtr]\ytr);
round(crossval('mse', x, y, 'Predfun', predfun), 3)

c = cvpartition(20, 'KFold', 4);
c.TestSize
find(test(c, 1))'
g = [ones(30, 1); 2*ones(10, 1)];
h = cvpartition(g, 'HoldOut', 0.25);
accumarray(g(test(h)), 1)'
c2 = repartition(c);
isequal(test(c, 1), test(c2, 1))

truth = categorical([repmat("apple", 20, 1); repmat("pear", 15, 1); repmat("plum", 10, 1)]);
guess = truth;
guess([3 7 22]) = "pear"; guess(30) = "apple"; guess([40 41]) = "pear";
[C, order] = confusionmat(truth, guess)
confusionchart(truth, guess, 'RowSummary', 'row-normalized', 'Title', 'Sorting');

y = [zeros(100, 1); ones(100, 1)];
good = [randn(100, 1); randn(100, 1) + 2];
poor = [randn(100, 1); randn(100, 1) + 0.5];
[x1, y1, ~, a1] = perfcurve(y, good, 1);
[x2, y2, ~, a2] = perfcurve(y, poor, 1);
round([a1 a2], 2)
plot(x1, y1, x2, y2, [0 1], [0 1], 'k:'), legend('good', 'poor', 'chance', 'Location', 'southeast'), xlabel('false positive rate'), ylabel('true positive rate')
